using System;
using System.IO;
using System.Threading;
using System.Diagnostics;

public static class FeatureTests {
 public static void Stereo(){using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"stereo-test.txt")))using(var connection=Open()){log.AutoFlush=true;int l,r;var watch=Stopwatch.StartNew();while(!connection.StereoLevels(out l,out r)&&watch.ElapsedMilliseconds<2000)Wait(connection,5);if(!connection.StereoLevels(out l,out r))throw new Exception("Stereo pair not ready");log.WriteLine("Original L="+l+" R="+r);int lead=Math.Max(l,r);if(lead==0){log.WriteLine("SKIP moving a silent master upward.");return;}int[] target=StereoLink.AtLevel(l,r,lead-1);bool restored=false;try{connection.SetStereoLevels(target[0],target[1]);watch.Restart();int a,b;while(watch.ElapsedMilliseconds<2000){if(connection.StereoLevels(out a,out b)&&a==target[0]&&b==target[1])break;Wait(connection,5);}if(!connection.StereoLevels(out a,out b)||a!=target[0]||b!=target[1])throw new Exception("Linked stereo write not confirmed");log.WriteLine("Confirmed linked decrease: L="+a+" R="+b);connection.SetStereoLevels(l,r);watch.Restart();while(watch.ElapsedMilliseconds<2000){if(connection.StereoLevels(out a,out b)&&a==l&&b==r){restored=true;break;}Wait(connection,5);}if(!restored)throw new Exception("Stereo restoration not confirmed");log.WriteLine("PASS: both original stereo levels restored.");}finally{int a,b;if(!restored&&connection.StereoLevels(out a,out b)&&a==target[0]&&b==target[1]){connection.SetStereoLevels(l,r);Wait(connection,200);}}}}
 public static void Writes(){using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"features-writes.txt")))using(var connection=Open()){log.AutoFlush=true;Wait(connection,7000);var original=connection.Channel(0);var master=connection.Channel(124);if(!original.NameComplete||!original.On.HasValue||!original.Solo.HasValue||!master.Level.HasValue)throw new Exception("Control state not loaded");connection.SetMute(0,original.On==0);connection.SetSolo(0,original.Solo==1);connection.SetLevel(124,master.Level.Value);Wait(connection,250);if(connection.Channel(0).On!=original.On||connection.Channel(0).Solo!=original.Solo||connection.Channel(124).Level!=master.Level)throw new Exception("Same-value output or switch readback differed");log.WriteLine("PASS: mute inversion, solo and stereo level accepted existing values without altering state.");string name=original.Name.Length<16?original.Name+".":original.Name.Substring(0,15)+".";bool restored=false;try{connection.Rename(0,name,original.ShortName);var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<3000&&connection.Channel(0).Name!=name)Wait(connection,20);if(connection.Channel(0).Name!=name)throw new Exception("Name write not confirmed");log.WriteLine("Desk confirmed temporary long name: "+name+"; short name unchanged: "+original.ShortName);connection.Rename(0,original.Name,original.ShortName);clock.Restart();while(clock.ElapsedMilliseconds<3000&&connection.Channel(0).Name!=original.Name)Wait(connection,20);if(connection.Channel(0).Name!=original.Name)throw new Exception("Name restoration not confirmed");restored=true;log.WriteLine("PASS: original long and short names restored.");}finally{if(!restored&&connection.Channel(0).Name==name){connection.Rename(0,original.Name,original.ShortName);Wait(connection,300);log.WriteLine("Restoration requested after failed name test.");}}connection.SetMixerView(0,0);Wait(connection,1500);var send=connection.Channel(0);if(!send.Level.HasValue||!send.SendOn.HasValue||!send.Pre.HasValue)throw new Exception("Send controls not loaded");connection.SetLevel(0,send.Level.Value);connection.SetSendOn(0,send.SendOn==1);connection.SetSendPre(0,send.Pre==1);Wait(connection,300);var after=connection.Channel(0);if(after.Level!=send.Level||after.SendOn!=send.SendOn||after.Pre!=send.Pre)throw new Exception("Send state changed unexpectedly");log.WriteLine("PASS: aux level, send switch and pre/post accepted current values; no audible level or routing changes made.");}}
 public static void AuxAll(){using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"aux-all.txt")))using(var connection=Open()){log.AutoFlush=true;connection.SetMixerView(6,-1);Wait(connection,1500);for(int aux=0;aux<12;aux++){connection.SetMixerView(0,aux);var deadline=Stopwatch.StartNew();MixerChannelState s;do{Wait(connection,50);s=connection.Channel(0);}while(deadline.ElapsedMilliseconds<8000&&(!connection.AuxModeValue.HasValue||!s.SendOn.HasValue||!s.Pre.HasValue||(connection.AuxModeValue==0&&!s.Level.HasValue)));log.WriteLine("Aux "+(aux+1)+" mode="+connection.AuxModeValue+" level="+s.Level+" on="+s.SendOn+" pre="+s.Pre+" error="+connection.Error);if(!connection.AuxModeValue.HasValue||!s.SendOn.HasValue||!s.Pre.HasValue||(connection.AuxModeValue==0&&!s.Level.HasValue))throw new Exception("Missing aux readback");}log.WriteLine("PASS all 12 aux sends and output-to-aux transition");}}
 public static void AuxProbe(){string[] a=File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"connection.ini"));uint input=0,output=0;foreach(var p in MidiInput.Devices())if(p.Value==a[0])input=p.Key;foreach(var p in FaderReader.Devices())if(p.Value==a[1])output=p.Key;using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"aux-probe.txt")))using(var source=new MidiInput(input))using(var sink=new FaderReader(output)){int dev=int.Parse(a[2]);foreach(var p in AuxSpecs()){log.WriteLine("TX "+BitConverter.ToString(p.Request(dev)));sink.ReadParameter(p,dev);}var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<1000){source.Pump();byte[] packet;while(source.Packets.TryDequeue(out packet))log.WriteLine("RX "+BitConverter.ToString(packet));Thread.Sleep(1);}}using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"aux-engine.txt")))using(var c=Open()){c.SetMixerView(0,0);for(int i=0;i<6;i++){Wait(c,1000);var s=c.Channel(0);log.WriteLine("time="+i+" mode="+c.AuxModeValue+" level="+s.Level+" on="+s.SendOn+" pre="+s.Pre+" error="+c.Error);}}}
 static System.Collections.Generic.IEnumerable<MixerParameter> AuxSpecs(){for(int i=0;i<12;i++){yield return MixerParameter.AuxMode(i);yield return MixerParameter.Level(0,i);yield return MixerParameter.SendOn(0,i);yield return MixerParameter.SendPre(0,i);}}public static FaderConnection Open(){string[] a=File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"connection.ini"));uint input=0,output=0;foreach(var p in MidiInput.Devices())if(p.Value==a[0])input=p.Key;foreach(var p in FaderReader.Devices())if(p.Value==a[1])output=p.Key;return new FaderConnection(input,output,int.Parse(a[2]));}
 static void Wait(FaderConnection connection,int ms){var time=Stopwatch.StartNew();while(time.ElapsedMilliseconds<ms){if(connection.Error!=null)throw new Exception(connection.Error);Thread.Sleep(10);}}
 public static void Read(){using(var w=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"features-hardware.txt")))using(var connection=Open()){w.AutoFlush=true;for(int view=0;view<=6;view++){connection.SetMixerView(view,-1);Wait(connection,view<4?7000:4000);int names=0;foreach(int id in FaderConnection.ViewIds(view)){var s=connection.Channel(id);w.WriteLine(MixerParameter.Title(id)+" | level="+MixerParameter.LevelLabel(id,s.Level)+" on="+s.On+" solo="+s.Solo+" name="+(s.Name??"LOADING")+" meter="+s.Meter);if(!s.Level.HasValue||!s.On.HasValue||(id<124&&!s.Solo.HasValue))throw new Exception("Incomplete channel state: "+id);if(s.NameComplete)names++;}w.WriteLine("View "+view+": "+names+" names loaded; solo status "+connection.SoloStatus);}connection.SetMixerView(0,0);Wait(connection,3000);for(int aux=0;aux<12;aux++){connection.SetMixerView(0,aux);Wait(connection,2700);var s=connection.Channel(0);w.WriteLine("Aux "+(aux+1)+" mode="+connection.AuxModeValue+" level="+s.Level+" on="+s.SendOn+" pre="+s.Pre);if(!connection.AuxModeValue.HasValue||!s.SendOn.HasValue||!s.Pre.HasValue||(connection.AuxModeValue==0&&!s.Level.HasValue))throw new Exception("Aux state missing: "+aux);}w.WriteLine("Stereo L="+connection.Channel(124).Level+" R="+connection.Channel(125).Level);w.WriteLine("PASS: all input/output banks, stereo master and 12 aux sends returned current state.");}}
}


